static long syz_fuse_drain_pipe_fd_limited(int fd, int max_loops,
					   const char* tag)
{
	char tmp[4096];
	long total = 0;
	long reads = 0;
	int empty_spins = 0;
	for (int i = 0; i < max_loops; i++) {
		ssize_t n = read(fd, tmp, sizeof(tmp));
		if (n > 0) {
			total += n;
			reads++;
			empty_spins = 0;
			continue;
		}
		if (n < 0 && (errno == EAGAIN || errno == EINTR)) {
			if (++empty_spins > 8)
				break;
			syz_fuse_sleep_ms(1);
			continue;
		}
		break;
	}
	if (tag)
		syz_fuse_kmsg2(tag, total, reads);
	return total;
}

