static pid_t syz_fuse_fork_hold_pipe_buffers(int pipefds[2], uint32_t mode,
					     int hold_ms, const char* tag)
{
	pid_t pid = fork();
	if (pid == 0) {
		int dup_pipe[2] = {-1, -1};
		int move_pipe[2] = {-1, -1};
		if (tag)
			syz_fuse_kmsg2(tag, pipefds[0], hold_ms);
		if (hold_ms < 1)
			hold_ms = 1;
		if (hold_ms > 250)
			hold_ms = 250;
		if (pipefds[0] >= 0) {
			(void)fcntl(pipefds[0], F_SETFL,
				    fcntl(pipefds[0], F_GETFL, 0) | O_NONBLOCK);
			if ((mode & SYZ_FUSE_SR_PIPE_TEE_AFTER_TEARDOWN) &&
			    pipe(dup_pipe) == 0) {
				ssize_t n;
				(void)fcntl(dup_pipe[0], F_SETFL, O_NONBLOCK);
				(void)fcntl(dup_pipe[1], F_SETFL, O_NONBLOCK);
				(void)fcntl(dup_pipe[1], F_SETPIPE_SZ, 16 * 1048576);
				n = syscall(__NR_tee, pipefds[0], dup_pipe[1],
					    16 * 1048576, SPLICE_F_NONBLOCK);
				syz_fuse_kmsg2("cleanup_pipe_hold_tee_after_teardown",
					       n, n < 0 ? -errno :
							  fcntl(dup_pipe[1], F_GETPIPE_SZ));
			}
			if (pipe(move_pipe) == 0) {
				ssize_t n;
				(void)fcntl(move_pipe[0], F_SETFL, O_NONBLOCK);
				(void)fcntl(move_pipe[1], F_SETFL, O_NONBLOCK);
				(void)fcntl(move_pipe[1], F_SETPIPE_SZ, 16 * 1048576);
				n = syscall(__NR_splice, pipefds[0], NULL, move_pipe[1],
					    NULL, 16 * 1048576,
					    SPLICE_F_MOVE | SPLICE_F_NONBLOCK);
				syz_fuse_kmsg2("cleanup_pipe_hold_splice_move_after_teardown",
					       n, n < 0 ? -errno :
							  fcntl(move_pipe[1], F_GETPIPE_SZ));
			}
			syz_fuse_sleep_ms(hold_ms);
			(void)syz_fuse_drain_pipe_fd_limited(
			    dup_pipe[0], 512, "cleanup_pipe_hold_tee_release_after_delay");
			(void)syz_fuse_drain_pipe_fd_limited(
			    move_pipe[0], 512, "cleanup_pipe_hold_move_release_after_delay");
			syz_fuse_close_pipe(dup_pipe);
			syz_fuse_close_pipe(move_pipe);
			syz_fuse_kmsg2("cleanup_pipe_hold_done_after_delay",
				       pipefds[0], hold_ms);
		}
		_exit(0);
	}
	return pid;
}
