static int syz_fuse_faulting_read(int read_fd, const char* mountpoint,
				  size_t read_len, uint32_t mode, int wait_ms)
{
	const size_t page_size = 4096;
	size_t alloc_len;
	char* map;
	int old_flags;
	pid_t umount_pid = -1;
	ssize_t n;
	if (read_len < FUSE_MIN_READ_BUFFER)
		read_len = FUSE_MIN_READ_BUFFER;
	if (read_len > 2097152)
		read_len = 2097152;
	alloc_len = ((read_len + page_size - 1) & ~(page_size - 1)) + page_size;
	map = (char*)mmap(NULL, alloc_len, PROT_READ | PROT_WRITE,
			  MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
	if (map == MAP_FAILED)
		return -1;
	memset(map, 0x5a, alloc_len);
	old_flags = fcntl(read_fd, F_GETFL, 0);
	if (old_flags >= 0)
		(void)fcntl(read_fd, F_SETFL, old_flags | O_NONBLOCK);
	if (mode & SYZ_FUSE_FR_UMOUNT_DURING_READ) {
		umount_pid = fork();
		if (umount_pid == 0) {
			syz_fuse_sleep_ms(wait_ms > 10 ? 10 : wait_ms);
			(void)umount2(mountpoint, MNT_DETACH);
			_exit(0);
		}
	}
	if (mode & SYZ_FUSE_FR_SHORT_READ) {
		n = read(read_fd, map, read_len);
	} else if (mode & SYZ_FUSE_FR_READV_SPLIT) {
		struct iovec iov[2];
		size_t first = page_size;
		if (read_len <= page_size)
			read_len = page_size * 2;
		if (mode & SYZ_FUSE_FR_FAULT_MPROTECT)
			(void)mprotect(map + page_size, page_size, PROT_NONE);
		else
			(void)munmap(map + page_size, page_size);
		iov[0].iov_base = map;
		iov[0].iov_len = first;
		iov[1].iov_base = map + page_size;
		iov[1].iov_len = read_len - first;
		n = readv(read_fd, iov, 2);
	} else {
		if (mode & SYZ_FUSE_FR_FAULT_MPROTECT)
			(void)mprotect(map + page_size, page_size, PROT_NONE);
		else if (mode & SYZ_FUSE_FR_FAULT_MUNMAP)
			(void)munmap(map + page_size, page_size);
		n = read(read_fd, map, read_len);
	}
	if (mode & SYZ_FUSE_FR_UMOUNT_AFTER_READ)
		(void)umount2(mountpoint, MNT_DETACH);
	if (mode & SYZ_FUSE_FR_DRAIN_AFTER_ERROR) {
		char tmp[FUSE_MIN_READ_BUFFER];
		ssize_t drain = read(read_fd, tmp, sizeof(tmp));
		(void)drain;
	}
	if (umount_pid > 0)
		syz_fuse_wait_or_kill(umount_pid);
	if (old_flags >= 0)
		(void)fcntl(read_fd, F_SETFL, old_flags);
	(void)munmap(map, alloc_len);
	return n == -1 ? -errno : (int)n;
}
