static int syz_fuse_dentry_send_before(int fd, uint64_t parent, uint64_t nodeid,
				       uint64_t child, const char* name, uint32_t mode,
				       uint64_t off, uint32_t size)
{
	if ((mode & SYZ_FUSE_DN_EXPIRE_FIRST) &&
	    syz_fuse_send_inval_entry(fd, parent, name, FUSE_EXPIRE_ONLY_FLAG) == -1)
		return -1;
	if ((mode & SYZ_FUSE_DN_DELETE_FIRST) &&
	    syz_fuse_send_delete(fd, parent, child, name) == -1)
		return -1;
	if ((mode & SYZ_FUSE_DN_INVAL_INODE_FIRST) &&
	    syz_fuse_send_inval_inode(fd, nodeid, off, size) == -1)
		return -1;
	if ((mode & SYZ_FUSE_DN_INC_EPOCH_FIRST) &&
	    syz_fuse_send_inc_epoch(fd) == -1)
		return -1;
	if ((mode & SYZ_FUSE_DN_PRUNE_FIRST) &&
	    syz_fuse_send_prune_one(fd, nodeid) == -1)
		return -1;
	return 0;
}

static int syz_fuse_dentry_send_after(int fd, uint64_t parent, uint64_t nodeid,
				      uint64_t child, const char* name, uint32_t mode,
				      uint64_t off, uint32_t size)
{
	if ((mode & SYZ_FUSE_DN_DELETE_AFTER) &&
	    syz_fuse_send_delete(fd, parent, child, name) == -1)
		return -1;
	if ((mode & SYZ_FUSE_DN_PRUNE_AFTER) &&
	    syz_fuse_send_prune_one(fd, nodeid) == -1)
		return -1;
	if ((mode & SYZ_FUSE_DN_EXPIRE_AFTER) &&
	    syz_fuse_send_inval_entry(fd, parent, name, FUSE_EXPIRE_ONLY_FLAG) == -1)
		return -1;
	if ((mode & SYZ_FUSE_DN_INVAL_INODE_AFTER) &&
	    syz_fuse_send_inval_inode(fd, nodeid, off, size) == -1)
		return -1;
	if ((mode & SYZ_FUSE_DN_INC_EPOCH_AFTER) &&
	    syz_fuse_send_inc_epoch(fd) == -1)
		return -1;
	return 0;
}
