	cleanup:
	if (have_thread)
		(void)pthread_join(thr, NULL);
	if (have_edge_thread)
		(void)pthread_join(edge_thr, NULL);
	if (file_pid > 0)
		syz_fuse_wait_or_kill(file_pid);
	if (live_hold_pid > 0)
		syz_fuse_wait_or_kill(live_hold_pid);
	if (poll_pid > 0)
		syz_fuse_wait_or_kill(poll_pid);
	if (materialize_pid > 0)
		syz_fuse_wait_or_kill(materialize_pid);
	if (poststore_fault_pid > 0)
		syz_fuse_wait_or_kill(poststore_fault_pid);
	if (postabort_fault_pid > 0)
		syz_fuse_wait_or_kill(postabort_fault_pid);
