		syz_fuse_prepare_fallback_req_out(&fallback_req);
	req_out = &fallback_req.req;
	file_nodeid = arg->file_nodeid ? arg->file_nodeid : 2;
	alias_nodeid = arg->alias_nodeid ? arg->alias_nodeid : file_nodeid;
	dir_nodeid = arg->dir_nodeid ? arg->dir_nodeid : 4;
	child_nodeid = arg->child_nodeid ? arg->child_nodeid : 5;
	child2_nodeid = arg->child2_nodeid ? arg->child2_nodeid : 7;
	store_size = arg->store_size ? arg->store_size : 4096;
