	mode = arg->mode;
		direct_nodeids = mode & (SYZ_FUSE_NSP_DELETE_FILE |
					 SYZ_FUSE_NSP_DELETE_ALIAS |
					 SYZ_FUSE_NSP_PRUNE_ALIAS |
					 SYZ_FUSE_NSP_DELETE_DIR |
					 SYZ_FUSE_NSP_PRE_RELOOKUP |
					 SYZ_FUSE_NSP_VALID_PRUNE_BATCH);
