			materialize_pid = fork();
			if (materialize_pid == 0) {
				syz_fuse_stateflip_child_op(mountpoint, sf_arg.mode, loops);
				_exit(0);
			}
		syz_fuse_kmsg2("nsp_materialize_start",
			       direct_lookup_mask ? direct_lookup_mask :
						    SYZ_FUSE_LOOKUP_HIT_FILE,
			       loops);
