			ret = syz_fuse_handle_one_available_stateflip(
			    read_fd, buf, buf_len, req_out, &st, wait_ms,
			    "syz_fuse_notify_sink_probe/materialize");
			if (ret < 0) {
				syz_fuse_kmsg2("nsp_materialize_error", ret, errno);
				goto out;
			}
