						early_op =
						    syz_fuse_notify_sink_read_processing_prefer_read_capture(
							clone_drain_fd, buf, buf_len, req_out,
							&st, wait_ms, loops * 32,
							"nsp_direct_read_early_prefer_clone",
							&captured_processing);
